import { Component, OnInit, ViewChild } from '@angular/core';
import { GResponse } from '../../../core/common/GResponse';
import { ActivatedRoute, Router } from '@angular/router';
import { ArticleFilterModel, IArticleFilterModel } from '../../../data/model/article/ArticleFilterModel';
import { ArticleService } from '../../../data/service/article/article.service';
import { G } from '../../../core/common/G';
import { IonContent, LoadingController, ToastController, MenuController } from '@ionic/angular';
import { SafeUrl } from '@angular/platform-browser';
import { SharedIonic } from '../../../core/common/SharedIonic';
import { SiteLanguageService } from '../../../core/i18n/site-language.service';

@Component({
  selector: 'app-page-article',
  templateUrl: './article.component.html',
  styleUrls: ['./article.component.scss']
})
export class ArticleComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;

  filteredArticles: IArticleFilterModel;
  queryText = '';
  segmentSelected = '2';
  articleSearch = '';
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  windowWidth = 1000;

  constructor(
    private router: Router,
    private articleService: ArticleService,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private activatedRoute: ActivatedRoute,
    private menuCtrl: MenuController,
    public language: SiteLanguageService) {

    // this.categories = [];

    // GResponse.ArticleCategory.forEach(c => {

    //   if (c.parentId != null) {
    //     this.categories.push(c);
    //   }
    // });
    G.getWindowWidth().subscribe(
      res => {
        this.windowWidth = res;
      }
    );
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  doRefresh(event) {

    setTimeout(() => {

      location.reload();

      event.target.complete();
    }, 2000);
  }

  changed() {

    SharedIonic.loading(this.loadingController);
    let filter: IArticleFilterModel;
    const page = 1;
    const take = 6;
    const title = this.queryText;
    filter = new ArticleFilterModel(page, take, title);
    this.filteredArticles = filter;

    this.getDate(filter);
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  getDate(filter: IArticleFilterModel) {

    this.segmentSelected = '2';
    if (this.segmentSelected == '1') {

      this.articleService.GetProductArticlesByFilter(filter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            this.filteredArticles = res.data;
          } else {
            SharedIonic.toast(this.toastController, 'موردی یافت نشد');
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
        }
      );
    } else {
      this.articleService.GetArticlesByFilter(filter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            this.filteredArticles = res.data;
          } else {
            SharedIonic.toast(this.toastController, 'موردی یافت نشد');
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
        }
      );
    }
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;

    let filter: IArticleFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      SharedIonic.loading(this.loadingController);

      const page = params.page;
      // Legacy store article links use the single course article archive.
      const segment = '2';

      this.segmentSelected = segment;

      if (page === undefined) {
        filter = new ArticleFilterModel();
      } else {

        const take = params.take ? params.take : 6;
        const title = params.title ? params.title : null;

        filter = new ArticleFilterModel(page, take, title);

      }
      this.filteredArticles = filter;

      this.getDate(filter);
    });
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.filteredArticles.startPage == null) {
      return;
    }
    if (this.filteredArticles.pageId > this.filteredArticles.startPage && +this.filteredArticles.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredArticles.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredArticles.endPage == null) {
      return;
    }
    if (this.filteredArticles.pageId < this.filteredArticles.endPage) {
      this.setQueryParams(+this.filteredArticles.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  setQueryParams(pageId: number) {

    this.content.scrollToTop(1500);

    this.router
      .navigate(
        ['Article'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredArticles.takeEntity ? this.filteredArticles.takeEntity : 6,
            title: this.articleSearch,
            segment: this.segmentSelected
          }
        });
  }

  toggleAppMenu() {
    this.menuCtrl.toggle('start');
  }

  quickFilter(keyword: string) {
    this.articleSearch = keyword;
    this.setQueryParams(1);
  }

}
